import React, { useEffect, useState } from "react";

import useApi from "../../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../../api/departmentsApi";
import { Loading } from "../../../../components";
import LaboratoryPaymentsTable from "./LaboratoryPaymentsTable";
import hospitalsApi from "../../../../api/hospitals/hospitalsApi";
import { useStateContext } from "../../../../contexts/ContextProvider";
import { toast, ToastContainer } from "react-toastify";

const columns = [
  { name: "Client", uid: "dependant_name" },
  { name: "Order Reference", uid: "order_reference_number" },
  { name: "Payment Reference", uid: "reference_number" },
  { name: "Payment Method", uid: "payment_method_title" },
  { name: "Amount", uid: "amount" },
  { name: "Status", uid: "status" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function LaboratoryPaymentsList() {
  const [openInventoryFormModal, setopenInventoryFormModal] = useState(false);
  const navigate = useNavigate();
  const [selectedPhysiotherapyService, setselectedPhysiotherapyService] = useState();
  const [laboratoryOrdersPayments, setlaboratoryOrdersPayments] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);
  const { loggedInUser } = useStateContext()
  const [statusFilter, setStatusFilter] = React.useState("");

  const laboratoryOrdersPaymentsApi = useApi(hospitalsApi.hospitalStaffAction);





  const getLaboratoryOrdersPayments = async (data) => {

    await laboratoryOrdersPaymentsApi.request({
      "action": "GetLaboratoryOrderPayments",

    });
  };

  useEffect(() => {
    if (laboratoryOrdersPaymentsApi.data) {
      if (laboratoryOrdersPaymentsApi.data.length) {
        setlaboratoryOrdersPayments(laboratoryOrdersPaymentsApi.data);
      }
    }
  }, [laboratoryOrdersPaymentsApi.data]);

  useEffect(() => {

    getLaboratoryOrdersPayments();


  }, []);

  useEffect(() => {
    setdata(laboratoryOrdersPayments);
  }, [laboratoryOrdersPayments]);

  const handleEditAction = (item) => {
    setopenInventoryFormModal(true);
    setselectedPhysiotherapyService(item);
    setmodalTitle(`EDIT ${item.laboratory_service_title}`);
    setUpdated(false)
  };

  const handleAddAction = () => {
    setopenInventoryFormModal(true);
    setmodalTitle("Add new pathology service");
    setselectedPhysiotherapyService(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (laboratoryOrdersPaymentsApi.data && laboratoryOrdersPaymentsApi.data.length) {
      setlaboratoryOrdersPayments(laboratoryOrdersPaymentsApi.data);
    }
    console.log("laboratoryOrdersApi.data", laboratoryOrdersPaymentsApi.data);
  }, [laboratoryOrdersPaymentsApi.data]);

  useEffect(() => {
    if (updated === true) {

      getLaboratoryOrdersPayments();
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(laboratoryOrdersPayments);
  }, [laboratoryOrdersPayments]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      laboratoryOrdersPayments &&
      laboratoryOrdersPayments.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        laboratoryOrdersPayments.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(laboratoryOrdersPayments);
    }
  };


  useEffect(()=>{
    if(statusFilter){
      toast.success(statusFilter)
    }
  },[statusFilter])

  return laboratoryOrdersPaymentsApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">
      <ToastContainer theme="light" position="bottom-center"/>

      <LaboratoryPaymentsTable
      statusFilter={statusFilter}
      setStatusFilter={setStatusFilter}
        title={"Laboratory Order Payments"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default LaboratoryPaymentsList;
